import type { BeatSettings, Look, Ttl } from '../types'
import { STATUS_HEARTS, VARIANTS } from './animations'

export const DEFAULTS: BeatSettings = {
  defaultOn: false,
  interval: 'auto',
  stopAfterHours: 8,
  stopAtUsage: 90,
  skipSmall: false,
  skipSmallTokens: 20_000,
  heartPlacement: 'tail',
  variant: 'classic',
  showCount: true,
  heartColor: 'claude',
  heartHex: '#e6a8b9',
  heartAnimate: true,
  heartEffect: 'steady',
  heartSpeed: 'normal',
  heartTiming: 'lubdub',
  statusLine: 'spaced',
  showCountdown: true,
  showTokens: true,
  statusHeart: 'beat',
  lineColor: 'claude',
  lineHex: '#e6a8b9',
  lineAnimate: true,
  lineEffect: 'steady',
  lineSpeed: 'normal',
  lineTiming: 'lubdub',
  onBeat: 'none',
  onStop: 'log',
  onModelSwitch: 'wait',
}

/** The interval `auto` beats at for each cache lifetime, in minutes: under it, with room for a slow request. */
export const AUTO: Record<Ttl, number> = { '1h': 50, '5m': 4 }

/** What the store keeps: the settings that differ from the defaults, so a new default reaches the rest. */
export const changed = (s: BeatSettings): Partial<BeatSettings> =>
  Object.fromEntries(Object.entries(s).filter(([k, v]) => v !== DEFAULTS[k as keyof BeatSettings]))

/** The parts that draw, and the settings each of them looks by. */
export type Part = 'heart' | 'line'
const LOOK_KEYS = {
  heart: { color: 'heartColor', customColor: 'heartHex', effect: 'heartEffect', animate: 'heartAnimate', speed: 'heartSpeed', timing: 'heartTiming' },
  line: { color: 'lineColor', customColor: 'lineHex', effect: 'lineEffect', animate: 'lineAnimate', speed: 'lineSpeed', timing: 'lineTiming' },
} as const satisfies Record<Part, Record<keyof Look, keyof BeatSettings>>

/** How a part draws and moves: its own color, effect, animation, speed and timing. */
export const lookOf = (s: BeatSettings, part: Part): Look => {
  const k = LOOK_KEYS[part]
  return { color: s[k.color], customColor: s[k.customColor], effect: s[k.effect], animate: s[k.animate], speed: s[k.speed], timing: s[k.timing] }
}

export const isObject = (x: unknown): x is Record<string, unknown> => typeof x === 'object' && x !== null && !Array.isArray(x)

/** Store values from an older or hand-edited store fall back to the default one by one. */
export function normalize(stored: unknown): BeatSettings {
  const s: Record<string, unknown> = { ...DEFAULTS }
  const from: Record<string, unknown> = isObject(stored) ? { ...stored } : {}
  // before 0.7.0 one look served both parts: each part takes it, unless it has its own
  for (const old of ['color', 'customColor', 'effect', 'animate', 'speed', 'timing'] as const) {
    if (!(old in from)) continue
    for (const part of ['heart', 'line'] as const) from[LOOK_KEYS[part][old]] ??= from[old]
    delete from[old]
  }
  for (const [k, v] of Object.entries(from)) {
    const isNumberFor = (...keys: string[]) => keys.includes(k) && typeof v === 'number'
    if (k in DEFAULTS && (typeof v === typeof DEFAULTS[k as keyof BeatSettings] || isNumberFor('heartSpeed', 'lineSpeed', 'interval'))) s[k] = v
  }
  const out = s as BeatSettings
  if (!VARIANTS.some(v => v.id === out.variant)) out.variant = DEFAULTS.variant
  if (!STATUS_HEARTS.includes(out.statusHeart)) out.statusHeart = DEFAULTS.statusHeart
  if (!['below', 'spaced', 'off'].includes(out.statusLine)) out.statusLine = DEFAULTS.statusLine
  for (const key of ['heartSpeed', 'lineSpeed'] as const) {
    if (typeof out[key] === 'number' && parseFrameMs(`${out[key]}`) === undefined) out[key] = DEFAULTS[key]
  }
  if (out.interval !== 'auto' && (typeof out.interval !== 'number' || parseMinutes(`${out.interval}`) === undefined)) out.interval = DEFAULTS.interval
  if (!['wait', 'warm'].includes(out.onModelSwitch)) out.onModelSwitch = DEFAULTS.onModelSwitch
  return out
}

export const FRAME_MS = { slow: 120, normal: 80, fast: 50 } as const
/** A frame's time: a named speed's, or the milliseconds typed in. */
export const frameMs = (look: Look) => (typeof look.speed === 'number' ? look.speed : FRAME_MS[look.speed])

// theme keys with a shimmer pair in Claude Code's themes, so they follow the active theme
export const THEME_COLORS = ['claude', 'permission', 'warning', 'fastMode', 'inactive'] as const
// drawn as hex, a raw color every surface takes; the highlight is a lighter shade
const PRESETS: Record<string, string> = {
  red: '#e5534b', magenta: '#c678dd', yellow: '#e5c07b', green: '#98c379', cyan: '#56b6c2', white: '#d7d7d7',
}
export const PRESET_COLORS = Object.keys(PRESETS)
export const COLORS = ['dim', ...THEME_COLORS, ...PRESET_COLORS, 'custom']

const lighten = (hex: string) => {
  const n = parseInt(hex.slice(1), 16)
  const ch = (shift: number) => {
    const c = (n >> shift) & 0xff
    return Math.round(c + (255 - c) * 0.45).toString(16).padStart(2, '0')
  }
  return `#${ch(16)}${ch(8)}${ch(0)}`
}
export const isHex = (v: string) => /^#[0-9a-f]{6}$/i.test(v)

/** A run of text in one style. `color` undefined with `dim` false is the terminal's own text color. */
export type Span = { text: string; color?: string; dim: boolean }
type Tone = { color?: string; dim: boolean }

/** The color's resting tone and its highlight: the theme's shimmer, a bright preset, a lighter hex. */
export function tones(s: Look): { base: Tone; hi: Tone } {
  const c = s.color
  if (c === 'dim') return { base: { dim: true }, hi: { dim: false } }
  if ((THEME_COLORS as readonly string[]).includes(c)) return { base: { color: c, dim: false }, hi: { color: `${c}Shimmer`, dim: false } }
  const hex = c === 'custom' ? (isHex(s.customColor) ? s.customColor : DEFAULTS.heartHex) : (PRESETS[c] ?? PRESETS.red!)
  return { base: { color: hex, dim: false }, hi: { color: lighten(hex), dim: false } }
}

/** A frame with a filled heart in it: the beat of the animation, where `flash` lights up. */
export const isLit = (frame: string) => /[♥❤]/.test(frame)

/** Characters as a terminal cell sees them: a heart's text-presentation selector stays with its heart. */
export const glyphs = (text: string) => [...text].reduce<string[]>((out, ch) => {
  if (ch === '︎' && out.length) out[out.length - 1] += ch
  else out.push(ch)
  return out
}, [])

type Mode = 'flash' | 'flow' | 'both'
const MODES: readonly Mode[] = ['flash', 'flow', 'both']
export const EPISODE = 40 // ticks one mixed mode lasts: 3.2s at normal speed

/**
 * The mode `mixed` plays at `tick`: drawn at random for each episode, never twice in a row. A hash of
 * the episode's number, not a stored roll, so every drawing at one tick agrees.
 */
export function mixedMode(tick: number): Mode {
  const roll = (n: number) => {
    let h = Math.imul(n ^ 0x9e3779b9, 0x85ebca6b)
    h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35)
    return ((h ^ (h >>> 16)) >>> 0) % 2
  }
  // each episode steps one or two modes on from the last, so it always changes
  let i = 0
  for (let n = 1; n <= Math.floor(tick / EPISODE); n++) i = (i + 1 + roll(n)) % 3
  return MODES[i]!
}

/**
 * Styles `text` by the color and effect: steady holds the resting tone, flash lights the whole
 * text while `lit`, flow sweeps a three-glyph highlight across it with `tick`, as the spinner's
 * shimmer does. Both does the two at once, the sweep dipping to the resting tone while lit;
 * mixed plays flash, flow or both, a few seconds of each.
 */
export function spans(text: string, s: Look, tick: number, lit: boolean): Span[] {
  const { base, hi } = tones(s)
  if (s.effect === 'steady' || !s.animate) return [{ text, ...base }]
  const mode = s.effect === 'mixed' ? mixedMode(tick) : s.effect
  if (mode === 'flash') return [{ text, ...(lit ? hi : base) }]
  const [rest, sweep] = mode === 'both' && lit ? [hi, base] : [base, hi]
  const g = glyphs(text)
  const at = (tick % (g.length + 6)) - 3
  const out: Span[] = []
  g.forEach((ch, i) => {
    const tone = Math.abs(i - at) <= 1 ? sweep : rest
    const last = out.at(-1)
    if (last && last.color === tone.color && last.dim === tone.dim) last.text += ch
    else out.push({ text: ch, ...tone })
  })
  return out
}

/** Reads a typed number into a setting's unit, undefined outside its range; it carries that unit and range. */
export type Reader = ((text: string) => number | undefined) & { unit: string; min: number; max: number }

/**
 * Reads a typed number with an optional unit (`units` maps each to its scale; '' is none), kept
 * when it lands within [min, max]: '35k' → 35000 tokens, '90m' → 1.5 hours.
 */
function reader(unit: string, units: Record<string, number>, min: number, max: number, isWhole: boolean): Reader {
  const read = (text: string): number | undefined => {
    const m = /^(\d+(?:\.\d+)?)\s*([a-z%]*)$/i.exec(text.trim().replaceAll(',', ''))
    const scale = m ? units[m[2]!.toLowerCase()] : undefined
    if (scale === undefined) return undefined
    const n = Number(m![1]) * scale
    const v = isWhole ? Math.round(n) : Math.round(n * 100) / 100
    return v >= min && v <= max ? v : undefined
  }
  return Object.assign(read, { unit, min, max })
}

export const parseTokens = reader('tokens', { '': 1, k: 1e3, m: 1e6 }, 1_000, 1_000_000, true)
export const parseMinutes = reader('minutes', { '': 1, m: 1, min: 1 }, 1, 55, true) // under the hour the cache lives
export const parseHours = reader('hours', { '': 1, h: 1, m: 1 / 60, min: 1 / 60 }, 0.5, 48, false)
export const parsePercent = reader('percent', { '': 1, '%': 1 }, 10, 100, true)
export const parseFrameMs = reader('ms a frame', { '': 1, ms: 1 }, 20, 500, true)

/** 184000 → 184k, 1250000 → 1.3M. */
export const tokens = (n: number) =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1).replace(/\.0$/, '')}M` : n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`

export type Value = string | number | boolean
/**
 * One row of the settings pane. A row of two choices (on/off among them) flips in place on Enter;
 * one of more, or that takes a typed value, opens a list, whose focused choice the preview shows
 * before it is picked. `help` is what the row does, shown while it is focused and above its list.
 */
export type Row = {
  key: keyof BeatSettings
  label: string
  name?: string // the label out of its tab, where it would be unclear: in Claude's transcript line
  values: readonly Value[]
  help: string
  show?: (s: BeatSettings) => boolean
  fmt?: (v: Value, s: BeatSettings) => string
  custom?: { placeholder: string; parse: Reader } // a typed value besides the choices
}

export type Preview = 'heart' | 'status' | 'both'
export type Tab = { id: string; title: string; rows: readonly Row[]; preview?: Preview }

const onOff = (v: Value) => (v ? 'on' : 'off')
const ALERTS = ['none', 'log', 'toast', 'both']
const alert = (v: Value) => (v === 'both' ? 'log + toast' : `${v}`)

/** The pane's own row on the Beating tab, not a setting: whether this session beats. */
export const SESSION_HELP = "Beats for this session alone. New sessions start as 'New sessions start' says."

const TERMINAL_ONLY = 'The desktop app draws no heart under the prompt: there the turn line carries it.'

/** The settings a part looks by, each its own: color, animation, effect, speed, timing. */
function lookRows(part: Part, what: string, shown: (s: BeatSettings) => boolean): Row[] {
  const k = LOOK_KEYS[part]
  const title = part === 'heart' ? 'Prompt heart' : 'Turn line'
  const moving = (s: BeatSettings) => shown(s) && (s[k.animate] as boolean)
  // the heart on the hint line is drawn dim, whatever its color
  const colored = part === 'heart' ? shown : (s: BeatSettings) => s.statusLine !== 'off'
  return [
    {
      key: k.color, label: 'Color', name: `${title} color`, values: COLORS, show: colored, fmt: (v, s) => (v === 'custom' ? `custom ${s[k.customColor]}` : `${v}`),
      help: `The color of ${what}: dim, your theme's, a preset, or any hex color.`,
    },
    {
      key: k.animate, label: 'Animate', name: `${title} animate`, values: [true, false], fmt: onOff,
      show: part === 'heart' ? () => true : (s: BeatSettings) => s.statusLine !== 'off',
      help: `Animates ${what}. Off, it holds still.`,
    },
    {
      key: k.effect, label: 'Effect', name: `${title} effect`, values: ['steady', 'flash', 'flow', 'mixed'], show: s => moving(s) && colored(s),
      help: 'steady; flash on each beat; flow, a shimmer sweeping across; mixed switches between them.',
    },
    {
      key: k.speed, label: 'Speed', name: `${title} speed`, values: ['slow', 'normal', 'fast'], show: part === 'heart' ? (s: BeatSettings) => s[k.animate] as boolean : moving,
      fmt: v => (typeof v === 'number' ? `${v}ms a frame` : `${v} · ${FRAME_MS[v as keyof typeof FRAME_MS]}ms`),
      help: `How fast ${what} plays: a speed, or a frame time.`,
      custom: { placeholder: 'e.g. 65ms', parse: parseFrameMs },
    },
    {
      key: k.timing, label: 'Timing', name: `${title} timing`, values: ['lubdub', 'linear'], show: part === 'heart' ? (s: BeatSettings) => s[k.animate] as boolean : moving,
      fmt: v => (v === 'lubdub' ? 'lub-dub' : 'linear'),
      help: `lub-dub beats twice, then rests, and suits the hearts; linear plays evenly, and suits the line animations (${VARIANTS.filter(x => x.isEndless).map(x => x.name).join(', ')}).`,
    },
  ]
}

export const TABS: readonly Tab[] = [
  {
    id: 'beating', title: 'Beating',
    rows: [
      { key: 'defaultOn', label: 'New sessions start', values: [false, true], fmt: onOff, help: 'Whether new sessions start beating. Open sessions keep what they have.' },
      {
        key: 'interval', label: 'Beat after idle', values: ['auto', 4, 15, 30, 45, 55], fmt: v => (v === 'auto' ? 'auto' : `${v}m`),
        help: `How long you're idle before a beat. auto fits your cache: every ${AUTO['1h']}m on a one-hour cache, every ${AUTO['5m']}m on a five-minute one.`,
        custom: { placeholder: 'e.g. 35m', parse: parseMinutes },
      },
      {
        key: 'onModelSwitch', label: 'After /model', values: ['wait', 'warm'],
        fmt: v => (v === 'wait' ? 'wait for your next turn' : 'warm the new model'),
        help: "After /model while you're idle: wait for your next message, or have the next beat write the new model's cache, at the cost your message would pay.",
      },
    ],
  },
  {
    id: 'limits', title: 'Limits',
    rows: [
      {
        key: 'stopAfterHours', label: 'Stop after idle', values: [1, 4, 8, 24], fmt: v => `${v}h`,
        help: 'Beating stops after this long without a message from you.',
        custom: { placeholder: 'e.g. 10h or 90m', parse: parseHours },
      },
      {
        key: 'stopAtUsage', label: 'Stop at usage', values: [80, 90, 100], fmt: v => `${v}%`,
        help: 'Beating stops once any of your usage limits reaches this.',
        custom: { placeholder: 'e.g. 85%', parse: parsePercent },
      },
      { key: 'skipSmall', label: 'Skip small chats', values: [false, true], fmt: onOff, help: "Doesn't beat chats smaller than the size below." },
      {
        key: 'skipSmallTokens', label: '  smaller than', values: [10_000, 20_000, 50_000, 100_000],
        show: s => s.skipSmall, fmt: v => `${tokens(Number(v))} tokens`,
        help: 'The smallest chat kept warm.',
        custom: { placeholder: 'e.g. 35k', parse: parseTokens },
      },
    ],
  },
  {
    id: 'heart', title: 'Prompt heart', preview: 'heart',
    rows: [
      {
        key: 'heartPlacement', label: 'Placement', name: 'Prompt heart placement', values: ['tail', 'line'], fmt: v => (v === 'tail' ? 'hint line · dim' : 'own line'),
        help: `At the end of the hint line under the prompt, drawn dim, or on a line of its own, in color. ${TERMINAL_ONLY}`,
      },
      {
        key: 'variant', label: 'Animation', name: 'Prompt heart animation', values: VARIANTS.map(v => v.id), fmt: v => VARIANTS.find(x => x.id === v)?.name ?? `${v}`,
        help: `What the heart under the prompt plays. ${TERMINAL_ONLY}`,
      },
      { key: 'showCount', label: 'Beat count', values: [true, false], fmt: onOff, help: `Shows ×3, the beats so far, beside the heart. ${TERMINAL_ONLY}` },
      ...lookRows('heart', 'the heart', s => s.heartPlacement === 'line'),
    ],
  },
  {
    id: 'status', title: 'Turn line', preview: 'status',
    rows: [
      {
        key: 'statusLine', label: 'Show', name: 'Turn line', values: ['spaced', 'below', 'off'],
        fmt: v => ({ spaced: 'after a blank line', below: 'right below the turn row', off: 'off' })[v as string]!,
        help: 'Where the line goes under your latest turn, or off. In the desktop app it sits above the prompt.',
      },
      { key: 'showCountdown', label: 'Countdown', values: [true, false], show: s => s.statusLine !== 'off', fmt: onOff, help: 'Shows the time to the next beat.' },
      { key: 'showTokens', label: 'Tokens kept', values: [true, false], show: s => s.statusLine !== 'off', fmt: onOff, help: 'Shows how much the last beat kept warm, as · 347k cached.' },
      {
        key: 'statusHeart', label: 'Its heart', name: 'Turn line heart', values: STATUS_HEARTS, show: s => s.statusLine !== 'off' && s.lineAnimate,
        fmt: v => (v === 'beat' ? 'one heart, beating' : v === 'off' ? 'still' : VARIANTS.find(x => x.id === v)?.name ?? `${v}`),
        help: 'What the heart starting the line plays. One heart beating keeps the words still; a wider animation moves them as it plays.',
      },
      ...lookRows('line', 'the line', s => s.statusLine !== 'off'),
    ],
  },
  {
    id: 'alerts', title: 'Alerts',
    rows: [
      { key: 'onBeat', label: 'On a beat', values: ALERTS, fmt: alert, help: 'How a beat landing is told: a line in the transcript (log), a toast, both, or nothing.' },
      { key: 'onStop', label: 'On stop', values: ALERTS, fmt: alert, help: 'How beating stopping on its own is told, and why.' },
    ],
  },
]

export const rowOf = (key: keyof BeatSettings) => {
  for (const tab of TABS) for (const row of tab.rows) if (row.key === key) return { tab, row }
  return undefined
}

/** A row Enter flips in place: two choices and no typed value. Any other opens its list. */
export const isFlip = (row: Row) => row.values.length === 2 && !row.custom

/**
 * `value` as `key` takes it, the way the pane does: one of the row's choices, or a custom value its
 * reader accepts (35000, or '35k'); a hex for the custom color. Undefined when it takes no such value.
 */
/** The hex each color row takes when it is custom. */
export const HEX_OF: Partial<Record<keyof BeatSettings, keyof BeatSettings>> = { heartColor: 'heartHex', lineColor: 'lineHex' }
export const HEX_KEYS: readonly string[] = Object.values(HEX_OF)

export function accept(key: string, value: unknown): Value | undefined {
  if (HEX_KEYS.includes(key)) return typeof value === 'string' && isHex(value) ? value.toLowerCase() : undefined
  const row = rowOf(key as keyof BeatSettings)?.row
  if (!row) return undefined
  if (row.values.includes(value as Value)) return value as Value
  return row.custom && (typeof value === 'number' || typeof value === 'string') ? row.custom.parse(String(value)) : undefined
}

/** A folder's own settings from the store: those of them the menu would take. */
export function normalizeOwn(stored: unknown): Partial<BeatSettings> {
  const kept = Object.entries(isObject(stored) ? stored : {}).flatMap(([k, v]) => {
    const value = accept(k, v)
    return value === undefined ? [] : [[k, value]]
  })
  return Object.fromEntries(kept)
}

files.hooks/tools.ts:
// The tools Claude calls to read and change cachebeat: their specs, drawn from the pane's rows so a
// range is written once, and the reading of a `set` call's input.
import type { ToolSpec } from 'claude-code'
import type { BeatSettings } from '../types'
import { shown } from './pane'
import type { Reader, Value } from './settings'
import { AUTO, DEFAULTS, HEX_KEYS, accept, isObject, parseMinutes, rowOf } from './settings'

/** Each setting, for the model; the unit and range are added from its reader. */
const ABOUT: Record<keyof BeatSettings, string> = {
  defaultOn: 'New sessions start beating; open sessions keep theirs.',
  interval:
    `Minutes idle before a beat, for sessions without their own; auto beats at ${AUTO['1h']} on a one-hour cache and ${AUTO['5m']} on a five-minute one, reading which the session has (state's cacheTtl).`,
  stopAfterHours: 'Beating stops after this long without a message from the user.',
  stopAtUsage: 'Beating stops once any usage limit reaches this.',
  skipSmall: 'Skips beating chats smaller than skipSmallTokens.',
  skipSmallTokens: "The smallest chat kept warm while skipSmall is on; setting it doesn't turn skipSmall on.",
  heartPlacement: 'The prompt heart: tail, at the end of the hint line, always dim; line, on its own line, in color. Terminal only.',
  variant: "The prompt heart's animation. Terminal only.",
  showCount: 'Shows the beat count beside the prompt heart. Terminal only.',
  heartColor: 'The prompt heart\'s color when it has its own line: dim, a theme color, a preset, or custom (heartHex).',
  heartHex: "The prompt heart's color when heartColor is custom; setting it doesn't set heartColor to custom.",
  heartAnimate: 'Animates the prompt heart.',
  heartEffect: 'The prompt heart on its own line: steady; flash on each beat; flow, a shimmer sweeping across; mixed switches between them.',
  heartSpeed: "The prompt heart's animation speed: a name, or a frame time.",
  heartTiming: 'The prompt heart: lubdub beats twice, then rests; linear plays evenly.',
  statusLine: 'The turn line, under the latest turn: spaced (after a blank line), below (right under it), or off. On desktop it sits above the prompt.',
  showCountdown: 'Shows the time to the next beat in the turn line.',
  showTokens: 'Shows the tokens the last beat kept warm in the turn line.',
  statusHeart: "What the heart starting the turn line plays: beat (one heart, filling in time), off (still), or one of the prompt heart's animations.",
  lineColor: 'The turn line\'s color: dim, a theme color, a preset, or custom (lineHex).',
  lineHex: "The turn line's color when lineColor is custom; setting it doesn't set lineColor to custom.",
  lineAnimate: "Animates the turn line's heart and effect.",
  lineEffect: 'The turn line: steady; flash on each beat; flow, a shimmer sweeping across; mixed switches between them.',
  lineSpeed: "The turn line's animation speed: a name, or a frame time.",
  lineTiming: "The turn line's heart: lubdub beats twice, then rests; linear plays evenly.",
  onBeat: 'How a beat is announced: a transcript line (log), a toast, both, or none.',
  onStop: 'How beating stopping on its own is announced.',
  onModelSwitch: "After /model while idle: wait for the user's next turn, or have the next beat write the new model's cache (a full cache write, the one that turn would make).",
}

const KEYS = Object.keys(ABOUT) as (keyof BeatSettings)[]
const range = (r: Reader) => `${r.min}–${r.max} ${r.unit}`
const names = (values: readonly Value[]) => values.filter(v => typeof v === 'string')

/** What a setting takes, as schemas: on/off, its named choices, or a number in its reader's range, with or beside names. */
function kinds(key: keyof BeatSettings): Record<string, unknown>[] {
  if (HEX_KEYS.includes(key)) return [{ type: 'string', pattern: '^#[0-9a-fA-F]{6}$' }]
  const { row } = rowOf(key)!
  if (typeof row.values[0] === 'boolean') return [{ type: 'boolean' }]
  if (!row.custom) return [{ enum: [...row.values] }]
  const r = row.custom.parse
  const named = names(row.values)
  return [...(named.length ? [{ enum: named }] : []), { type: 'number', minimum: r.min, maximum: r.max }]
}

/** A setting's schema: what it takes, or null to reset it. */
function field(key: keyof BeatSettings): Record<string, unknown> {
  const r = HEX_KEYS.includes(key) ? undefined : rowOf(key)!.row.custom?.parse
  return { anyOf: [...kinds(key), { type: 'null' }], description: r ? `${ABOUT[key]} (${range(r)})` : ABOUT[key] }
}

/** What a setting takes, each choice in words, for a refusal. */
function takes(key: keyof BeatSettings): string[] {
  if (HEX_KEYS.includes(key)) return ['a hex color (#rrggbb)']
  const { row } = rowOf(key)!
  if (typeof row.values[0] === 'boolean') return ['true', 'false']
  if (!row.custom) return row.values.map(String)
  return [...names(row.values), range(row.custom.parse)]
}

/** `a, b, or c`; `a or b`. */
const either = (choices: string[]) =>
  choices.length < 3 ? choices.join(' or ') : `${choices.slice(0, -1).join(', ')}, or ${choices.at(-1)}`

const object = (properties: Record<string, unknown>) => ({ type: 'object', properties, additionalProperties: false })

export const STATE: ToolSpec = {
  name: 'state',
  description: [
    "cachebeat's state in this session, every setting as it applies here, and this folder's own settings.",
    [
      '`settings` are the values in effect in this session: this folder\'s own over those for all folders. `folder` is this session\'s folder (`path`) and the settings it has of its own (`own`). `allFolders`, shown while the folder has any of its own, has the settings for all folders.',
      "`nextBeat` is `in 42m` (mid-turn too: counted from the end of the turn's last request, for a turn that goes quiet), `50m after the request on its way` (a request of the turn is being answered), `after this turn` (a turn whose beats wait for its end), `after the next turn` (nothing cached to keep warm yet), or null when off or skipping.",
      '`intervalFrom` is `session` when this session has its own interval, `folder` when it follows this folder\'s own, `all folders` when it follows the interval for all folders in minutes, and `auto` when that is auto.',
      "`cacheTtl` is how long this session's cache lives, `1h` or `5m`, worked out on each call from Claude Code's cache settings and whether a subscription is within its usage; an auto interval beats within it (50 or 4 minutes).",
      '`skipping`, when set, says why beats skip this chat (under the skipSmallTokens minimum).',
      "`paused`, when set, says why beats wait for the user's next turn (a model switch, a compaction); only that turn ends it, not `set`.",
      'A beat re-sends the conversation as this session last sent it, with one short line tagged `[cachebeat]` asking for a one-character reply, which is thrown away. It reads the cached conversation (`lastBeatReadTokens`, the last beat\'s) and writes only what wasn\'t cached (`lastBeatWrittenTokens`), usually a few tokens; both are null before the first beat. `defaults` has the default of each setting that differs from it.',
    ].join(' '),
  ].join('\n\n'),
  inputSchema: object({}),
}

export const SET: ToolSpec = {
  name: 'set',
  description: [
    "Changes cachebeat, which keeps this session's prompt cache warm while it sits idle by sending a small background request, a beat, shortly before the cache would expire. Change only what the user asks for.",
    '`session` is this session alone. `settings` is saved for all folders and used by every session, open ones included: `settings.interval` is the default interval, `settings.defaultOn` whether new sessions start on (open sessions keep theirs). `folder` is saved for this session\'s folder alone (state\'s `folder.path`), takes any setting, and wins over `settings` there; `null` for one setting drops it, so it follows all folders again, and `folder: null` drops every one. In `settings`, `null` puts a setting back to its default. When you change a setting, say where it applies: all folders, or this folder by its path, since a subfolder or another worktree has settings of its own.',
    'A request that names no scope ("turn it on", "beat every 20 minutes") is for this session. "In this repo", "in this folder", "here" or "for this project" mean `folder`. "Default", "new sessions", "every session", "everywhere", "always" or "from now on" mean `settings`. If you can\'t tell which the user means, ask. A change to `settings` doesn\'t reach a setting this folder has its own of (`state`\'s `folder.own`): tell the user.',
    "Each beat counts toward the user's usage. The first time in a conversation a change starts beating or changes how often a beating session beats, say so once.",
    'Setting `intervalMinutes` turns beating on too, unless `enabled: false` comes with it. Saving an interval in `settings` or `folder` drops this session\'s own, so it beats at the saved one, unless `intervalMinutes` comes with it; `intervalMinutes: null` alone makes it follow the settings.',
    'Nothing changes if any value is invalid, and the refusal names each one. Subagents can read `state` but not call this. Returns what changed, this session\'s state, and the changed settings: for all folders, and for this folder with its `path`, which you name to the user.',
  ].join('\n\n'),
  inputSchema: object({
    session: object({
      enabled: { type: 'boolean', description: 'Beat in this session.' },
      intervalMinutes: {
        anyOf: [{ type: 'number', minimum: parseMinutes.min, maximum: parseMinutes.max }, { type: 'null' }],
        description: `This session's interval in minutes, which turns beating on; null follows settings.interval, auto included. (${range(parseMinutes)})`,
      },
    }),
    settings: object(Object.fromEntries(KEYS.map(k => [k, field(k)]))),
    folder: {
      anyOf: [object(Object.fromEntries(KEYS.map(k => [k, field(k)]))), { type: 'null' }],
      description: "This folder's own settings, as `settings` takes them; a setting's null drops it, so it follows all folders, and null for the whole drops every one.",
    },
  }),
}

/**
 * A `set` call's input, as read: this session's switch and interval (null follows the settings), the
 * settings to save for all folders, and this folder's own to save and drop (null drops every one).
 */
export type SetChange = {
  enabled?: boolean; intervalMinutes?: number | null; patch: Partial<BeatSettings>
  folder?: { own: Partial<BeatSettings>; drop: (keyof BeatSettings)[] } | null
}

/** Reads a `set` call's input whole, or says every value it refuses. */
export function parseSet(input: { session?: unknown; settings?: unknown; folder?: unknown }): SetChange | { error: string } {
  const change: SetChange = { patch: {} }
  const bad: string[] = []
  const said = (v: unknown) => JSON.stringify(v)
  for (const part of ['session', 'settings'] as const) {
    if (input[part] !== undefined && !isObject(input[part])) bad.push(`${part} is an object, not ${said(input[part])}`)
  }
  if (input.folder !== undefined && input.folder !== null && !isObject(input.folder)) bad.push(`folder is an object or null, not ${said(input.folder)}`)
  const session = isObject(input.session) ? input.session : {}
  const settings = isObject(input.settings) ? input.settings : {}
  for (const [k, v] of Object.entries(session)) {
    if (k === 'enabled') {
      if (typeof v === 'boolean') change.enabled = v
      else bad.push(`session.enabled takes true or false, not ${said(v)}`)
    } else if (k === 'intervalMinutes') {
      const m = v === null ? null : typeof v === 'number' || typeof v === 'string' ? parseMinutes(String(v)) : undefined
      if (m !== undefined) change.intervalMinutes = m
      else bad.push(`session.intervalMinutes takes ${range(parseMinutes)} or null, not ${said(v)}`)
    } else bad.push(`session has no ${k}`)
  }
  for (const [k, v] of Object.entries(settings)) {
    if (!(k in ABOUT)) {
      bad.push(`settings has no ${k}`)
      continue
    }
    const key = k as keyof BeatSettings
    const value = v === null ? DEFAULTS[key] : accept(key, v)
    if (value === undefined) bad.push(`settings.${key} takes ${either([...takes(key), 'null'])}, not ${said(v)}`)
    else change.patch = { ...change.patch, [key]: value }
  }
  if (input.folder === null) change.folder = null
  else if (isObject(input.folder)) {
    const folder: NonNullable<SetChange['folder']> = { own: {}, drop: [] }
    for (const [k, v] of Object.entries(input.folder)) {
      if (!(k in ABOUT)) {
        bad.push(`folder has no ${k}`)
        continue
      }
      const key = k as keyof BeatSettings
      const value = v === null ? null : accept(key, v)
      if (value === undefined) bad.push(`folder.${key} takes ${either([...takes(key), 'null'])}, not ${said(v)}`)
      else if (value === null) folder.drop.push(key)
      else folder.own = { ...folder.own, [key]: value }
    }
    change.folder = folder
  }
  // an interval of its own is asked for to beat at, as `/cachebeat <minutes>` takes it
  if (typeof change.intervalMinutes === 'number') change.enabled ??= true
  return bad.length ? { error: `nothing changed: ${bad.join('; ')}` } : change
}

/** A setting's name as the pane labels it, or as it reads out of its tab. */
export function label(key: keyof BeatSettings) {
  if (HEX_KEYS.includes(key)) return key === 'heartHex' ? 'Prompt heart color' : 'Turn line color'
  const { row } = rowOf(key)!
  return row.name ?? row.label.trim()
}

/**
 * A `set` call in one line, as the transcript shows it, `path` naming this folder:
 * `this session on, every 20m · all folders: Beat after idle 30m · this folder (…/api): New sessions start on`.
 */
export function summary(change: SetChange, s: BeatSettings, path: string) {
  const here = [
    change.enabled !== undefined && (change.enabled ? 'on' : 'off'),
    change.intervalMinutes !== undefined && (change.intervalMinutes === null ? 'its own interval dropped' : `every ${change.intervalMinutes}m`),
  ].filter(Boolean)
  const each = (patch: Partial<BeatSettings>) => (Object.entries(patch) as [keyof BeatSettings, Value][]).map(([key, v]) =>
    `${label(key)} ${HEX_KEYS.includes(key) ? v : shown(rowOf(key)!.row, v, s)}`,
  )
  const saved = each(change.patch)
  const own = change.folder ? [...each(change.folder.own), ...change.folder.drop.map(k => `${label(k)} as all folders`)] : []
  return [
    here.length ? `this session ${here.join(', ')}` : '',
    saved.length ? `all folders: ${saved.join(', ')}` : '',
    change.folder === null ? `this folder (${path}) follows all folders again` : own.length ? `this folder (${path}): ${own.join(', ')}` : '',
  ].filter(Boolean).join(' · ') || 'no change'
}

